def correct_bracketing(brackets: str):
    # Verify that the input string contains only '<' and '>' characters
    if set(brackets) != {'<', '>'}:
        return False

    # Count the number of opening and closing brackets in the input string
    open_count = brackets.count('<')
    close_count = brackets.count('>')

    # Check if the number of opening brackets is equal to the number of closing brackets
    if open_count != close_count:
        return False

    # Iterate through the input string and check if the brackets are correctly nested
    stack = []
    for bracket in brackets:
        if bracket == '<':
            stack.append(bracket)
        elif bracket == '>':
            if not stack:
                return False
            stack.pop()

    # Return True if all conditions are met, otherwise return False
    return len(stack) == 0
