def sort_numbers(numbers: str) -> str:
    numberals = numbers.split()
    numberal_to_num = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    num_to_numberal = {v: k for k, v in numberal_to_num.items()}

    sorted_numbers = sorted([numberal_to_num[num] for num in numberals])
    sorted_numberals = [num_to_numberal[num] for num in sorted_numbers]

    return ' '.join(sorted_numberals)
